var bProp = bt("proposta", "proposta", "Gerar Proposta", ' title="Gerar a proposta comercial deste orçamento"', "primary");
var abasJan = { planilha: 1, sintetico: 1, insumos: 1, cronograma: 1, execucao: 1, graficos: 1, relatorios: 1 };
