var g = this.hxGeo(pro, num0(m.janela && m.janela.dias) || 1);
var rowH = this.LX_ROWH, T = this.LX_TOPO, corpoH = Math.max(1, locais.length) * rowH, A = T + corpoH + 12;
function Y(idx) { return T + idx * rowH + rowH / 2; }
