locais.forEach(function (L, i) {
if (i % 2 === 1) s += '<rect x="0" y="' + f1(T + i * rowH) + '" width="' + f1(g.W) + '" height="' + f1(rowH) + '" fill="#f8fafc"/>';
});
s += this.hxMarcasSvg(pro, g.pxDia, T + corpoH, A - 2);
