if (!m || m.ok !== true) { out.estado = "recusou"; out.motivo = (m && m.motivo) || "O motor do macrofluxo recusou o desenho e não disse por quê."; return out; }
out.estado = "ok"; out.m = m; out.nivel = nivel;
return out;
